import pandas as pd


def _is_null(v):
    try:
        return pd.isna(v)
    except (TypeError, ValueError):
        return v is None


def _values_differ(a, b):
    a_null = _is_null(a)
    b_null = _is_null(b)
    if a_null and b_null:
        return False
    if a_null != b_null:
        return True
    return a != b


def run(inputs: dict) -> dict:
    dim_in = inputs["DIM_CUSTOMER"]
    stg_in = inputs["STG_CUSTOMER"]

    # Work on copies, preserve columns/dtypes as much as possible.
    dim = dim_in.copy().reset_index(drop=True)

    cols = ["customer_id", "name", "segment", "eff_start_date", "eff_end_date", "is_current"]
    for c in cols:
        if c not in dim.columns:
            dim[c] = pd.NA

    stg = stg_in.copy()

    if len(stg) == 0:
        return {"dim_customer_out": dim[cols].copy()}

    # Step 1: Deduplicate STG_CUSTOMER to the latest record per customer_id
    # by update_date; ties broken by greater (name, segment) lexicographically.
    stg_sorted = stg.sort_values(
        by=["customer_id", "update_date", "name", "segment"],
        ascending=[True, False, False, False],
        kind="mergesort",
    )
    dedup = stg_sorted.drop_duplicates(subset="customer_id", keep="first")

    new_rows = []

    for _, s in dedup.iterrows():
        cust_id = s["customer_id"]
        s_name = s["name"]
        s_segment = s["segment"]
        s_update_date = s["update_date"]

        mask_current = (dim["customer_id"] == cust_id) & (dim["is_current"] == 1)
        current_idx = dim.index[mask_current]

        if len(current_idx) == 0:
            new_rows.append({
                "customer_id": cust_id,
                "name": s_name,
                "segment": s_segment,
                "eff_start_date": s_update_date,
                "eff_end_date": pd.NaT,
                "is_current": 1,
            })
        else:
            ci = current_idx[0]
            c_name = dim.at[ci, "name"]
            c_segment = dim.at[ci, "segment"]

            if _values_differ(c_name, s_name) or _values_differ(c_segment, s_segment):
                dim.at[ci, "eff_end_date"] = s_update_date
                dim.at[ci, "is_current"] = 0

                new_rows.append({
                    "customer_id": cust_id,
                    "name": s_name,
                    "segment": s_segment,
                    "eff_start_date": s_update_date,
                    "eff_end_date": pd.NaT,
                    "is_current": 1,
                })
            # else: unchanged -> no new version created

    if new_rows:
        new_df = pd.DataFrame(new_rows, columns=cols)
        result = pd.concat([dim[cols], new_df], ignore_index=True)
    else:
        result = dim[cols].copy()

    return {"dim_customer_out": result}
